namespace LostAndFound.Api.Features.Items;

public class FoundItem
{
    public const string DefaultHeldAt = "With finder";

    public Guid Id { get; private set; }

    /// <summary>Sequential human-facing number, shown as "Nº 0413". Generated by Postgres.</summary>
    public int Number { get; private set; }

    public Guid UserFoundId { get; private set; }

    /// <summary>Finder's display name at the moment of posting (we have no users table yet).</summary>
    public string FinderName { get; private set; } = string.Empty;

    public string Name { get; private set; } = string.Empty;
    public string Description { get; private set; } = string.Empty;
    public ItemCategory Category { get; private set; }

    /// <summary>Where it was found: "Library · 2nd floor".</summary>
    public string Cabinet { get; private set; } = string.Empty;

    /// <summary>Where the item is now: "With finder", "Security desk", "Library desk".</summary>
    public string HeldAt { get; private set; } = DefaultHeldAt;

    public FoundItemStatus Status { get; private set; }
    public DateTimeOffset FoundAt { get; private set; }
    public DateTimeOffset CreatedAt { get; private set; }
    public string? PhotoKey { get; private set; }

    private FoundItem()
    { }

    public FoundItem(
        Guid userFoundId,
        string finderName,
        string name,
        string description,
        ItemCategory category,
        string cabinet,
        string? heldAt,
        DateTimeOffset foundAt,
        string? photoKey = null)
    {
        Id = Guid.NewGuid();
        UserFoundId = userFoundId;
        FinderName = finderName;
        Name = name;
        Description = description;
        Category = category;
        Cabinet = cabinet;
        HeldAt = string.IsNullOrWhiteSpace(heldAt) ? DefaultHeldAt : heldAt.Trim();
        Status = FoundItemStatus.Open;
        FoundAt = foundAt.ToUniversalTime();
        CreatedAt = DateTimeOffset.UtcNow;
        PhotoKey = photoKey;
    }

    public void MarkReturned()
    {
        Status = FoundItemStatus.Returned;
    }

    public void SetPhoto(string photoKey)
    {
        if (string.IsNullOrWhiteSpace(photoKey))
            throw new ArgumentException("Photo key cannot be empty.", nameof(photoKey));

        PhotoKey = photoKey;
    }
}
